#include <stdio.h>

/* teste do desafio de MODULO as-vendas-do-dia — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: o teste chama as funcoes do aluno pelo prototipo. As duas
   primeiras sao conferidas pelo valor DEVOLVIDO; a terceira nao devolve nada e
   e conferida pelo EFEITO na lista, que o teste le posicao a posicao depois da
   chamada — e isso so funciona porque a lista chega por endereco. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int oTotalDoDia(int vendas[], int n);
int aMaiorVenda(int vendas[], int n);
void ordenarDecrescente(int vendas[], int n);

SM_TEST(o_total_e_a_maior_do_dia_cheio) {
    /* um dia comum: cinco vendas, nenhuma repetida */
    int vendas[5] = {120, 45, 300, 80, 15};
    checa_int("o total do dia", oTotalDoDia(vendas, 5), 560,
              "o laco soma as cinco: 120 + 45 + 300 + 80 + 15");
    checa_int("a maior venda", aMaiorVenda(vendas, 5), 300,
              "a maior nao e a primeira nem a ultima: so achando pelo percurso");
}

SM_TEST(o_tamanho_manda_e_nao_a_lista) {
    /* a MESMA lista, com n menor: a funcao so pode olhar os 3 primeiros */
    int vendas[5] = {120, 45, 300, 80, 15};
    checa_int("o total dos tres primeiros", oTotalDoDia(vendas, 3), 465,
              "com n igual a 3 a soma para no terceiro: 120 + 45 + 300");
    checa_int("a maior dos dois primeiros", aMaiorVenda(vendas, 2), 120,
              "com n igual a 2 o 300 nem e olhado: quem manda no percurso e o n");
}

SM_TEST(a_lista_vazia_e_a_de_um_so) {
    int nenhuma[1] = {0};
    checa_int("o total da lista vazia", oTotalDoDia(nenhuma, 0), 0,
              "sem volta nenhuma o acumulador fica como comecou");
    checa_int("a maior da lista vazia", aMaiorVenda(nenhuma, 0), -1,
              "nao ha maior quando nao ha venda: o -1 e a guarda");
    int uma[1] = {77};
    checa_int("a maior da lista de um", aMaiorVenda(uma, 1), 77,
              "com um item so, ele e a maior — o laco nem chega a rodar");
}

SM_TEST(a_ordenacao_muda_a_lista_de_fora) {
    int vendas[5] = {120, 45, 300, 80, 15};
    ordenarDecrescente(vendas, 5);
    checa_int("a primeira depois de ordenar", vendas[0], 300,
              "a maior venda foi para a frente da lista");
    checa_int("a segunda depois de ordenar", vendas[1], 120,
              "a segunda maior vem logo atras");
    checa_int("a terceira depois de ordenar", vendas[2], 80,
              "o top 3 do dia sai das tres primeiras posicoes");
    checa_int("a ultima depois de ordenar", vendas[4], 15,
              "a menor venda foi para o fim");
    checa_int("o total nao mudou com a ordem", oTotalDoDia(vendas, 5), 560,
              "ordenar reordena, nao cria nem perde venda");
}

