#include <stdio.h>

int oTotalDoDia(int vendas[], int n) {
    int total = 0;
    for (int i = 0; i < n; i++) {
        total = total + vendas[i];
    }
    return total;
}

int aMaiorVenda(int vendas[], int n) {
    if (n == 0) {
        return -1;
    }
    int maior = vendas[0];
    for (int i = 1; i < n; i++) {
        if (maior < vendas[i]) {
            maior = vendas[i];
        }
    }
    return maior;
}

void ordenarDecrescente(int vendas[], int n) {
    for (int passada = 0; passada < n - 1; passada++) {
        for (int j = 0; j < n - 1 - passada; j++) {
            if (vendas[j] < vendas[j + 1]) {
                int guardado = vendas[j];
                vendas[j] = vendas[j + 1];
                vendas[j + 1] = guardado;
            }
        }
    }
}
